#include <iostream>
#include <vector>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<vector<int>> grid(n, vector<int>(n));
    int zero_r = -1, zero_c = -1;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            cin >> grid[i][j];
            if (grid[i][j] == 0) {
                zero_r = i;
                zero_c = j;
            }
        }
    }

    int full_r = (zero_r == 0) ? 1 : 0;
    long long target_sum = 0;
    for (int j = 0; j < n; ++j) {
        target_sum += grid[full_r][j];
    }

    long long current_sum = 0;
    for (int j = 0; j < n; ++j) {
        current_sum += grid[zero_r][j];
    }

    long long missing_value = target_sum - current_sum;

    cout << missing_value << "\n";
    cout << zero_r + 1 << "\n";
    cout << zero_c + 1 << "\n";

    return 0;
}
